import { query } from '../db.js';

// Callback-style database access. Chapter 5 migrates this to UserRepository.
export function findByEmail(email, callback) {
  query('users', (u) => u.email === email && u.deleted_at === null, (err, rows) => {
    if (err) return callback(err);
    callback(null, rows[0] ?? null);
  });
}

export function isActive(email, callback) {
  findByEmail(email, (err, user) => {
    if (err) return callback(err);
    callback(null, Boolean(user));
  });
}
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { findByEmail, isActive } from '../src/services/auth-service.js';

test('findByEmail ignores soft-deleted users', (t, done) => {
  findByEmail('alan@example.com', (err, user) => {
    assert.equal(err, null);
    assert.equal(user, null);
    done();
  });
});

test('isActive is true for a live user', (t, done) => {
  isActive('ada@example.com', (err, active) => {
    assert.equal(err, null);
    assert.equal(active, true);
    done();
  });
});
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { listActiveUsers, findUser } from '../src/services/user-service.js';

test('listActiveUsers excludes soft-deleted users', (t, done) => {
  listActiveUsers((err, users) => {
    assert.equal(err, null);
    assert.equal(users.length, 2);
    assert.ok(users.every((u) => u.deleted_at === null));
    done();
  });
});

test('findUser returns null for an unknown id', (t, done) => {
  findUser(999, (err, user) => {
    assert.equal(err, null);
    assert.equal(user, null);
    done();
  });
});
